// TODO: Re-enable when /search endpoint is implemented
// These tests define the specification for a standalone search module
// Currently search is at /products/search as part of catalog module
describe.skip('Search Module - TDD London School', () => {
  let app: Express;

  beforeEach(() => {
    // Reset all mocks before each test
    jest.clearAllMocks();
  });

  describe('GET /search - Basic Search Functionality - REQ-SRCH-001', () => {
    it('should return products matching keyword search', async () => {
      // Arrange - Setup mock expectations
      const searchQuery = 'dog food';
      mockPrisma.product.findMany.mockResolvedValue([sampleProducts[0]]);
      mockPrisma.product.count.mockResolvedValue(1);
      mockSearchEngine.search.mockResolvedValue({
        products: [sampleProducts[0]],
        total: 1,
        relevanceScores: { 'prod-001': 0.95 },
      });

      // Act
      const response = await request(app)
        .get('/search')
        .query({ q: searchQuery, page: 1, pageSize: 20 })
        .expect(200);

      // Assert - Verify collaboration pattern
      expect(mockSearchEngine.search).toHaveBeenCalledWith({
        query: searchQuery,
        filters: {},
        pagination: { page: 1, pageSize: 20 },
        sort: 'relevance',
      });

      expect(response.body).toMatchObject({
        success: true,
        data: {
          products: [
            {
              id: 'prod-001',
              name: 'Premium Dog Food - Chicken & Rice',
              price: 49.99,
              rating: 4.5,
              inStock: true,
            },
          ],
          pagination: {
            page: 1,
            pageSize: 20,
            total: 1,
            totalPages: 1,
          },
        },
      });
    });

    it('should return empty results for no matches', async () => {
      // Arrange
      mockPrisma.product.findMany.mockResolvedValue([]);
      mockPrisma.product.count.mockResolvedValue(0);
      mockSearchEngine.search.mockResolvedValue({
        products: [],
        total: 0,
